import { useCallback, useEffect, useState } from "react";

/** Persisted state hook — everything in hrToolkit stays on-device. */
export function useLocalStorage<T>(key: string, initial: T) {
  const [value, setValue] = useState<T>(() => {
    try {
      const raw = localStorage.getItem(key);
      return raw != null ? (JSON.parse(raw) as T) : initial;
    } catch {
      return initial;
    }
  });

  useEffect(() => {
    try {
      localStorage.setItem(key, JSON.stringify(value));
    } catch {
      /* quota / private mode — ignore */
    }
  }, [key, value]);

  const reset = useCallback(() => setValue(initial), [initial]);
  return [value, setValue, reset] as const;
}

export const cn = (...parts: (string | false | null | undefined)[]) =>
  parts.filter(Boolean).join(" ");

import { describe, it, expect } from "vitest";
import { progressiveTax, daysBetween, ymd, n } from "./calc";

describe("progressiveTax", () => {
  const slabs: [number, number][] = [
    [300000, 0], [700000, 0.05], [1000000, 0.1],
    [1200000, 0.15], [1500000, 0.2], [Infinity, 0.3],
  ];

  it("is zero below the first taxable band", () => {
    expect(progressiveTax(250000, slabs)).toBe(0);
  });

  it("taxes only the slice within each band", () => {
    // 3–7L @ 5% = 20,000 on income of exactly 7L
    expect(progressiveTax(700000, slabs)).toBe(20000);
  });

  it("accumulates across bands", () => {
    // 20,000 (3–7L) + 30,000 (7–10L) + 30,000 (10–12L @15%) = 80,000 at 12L
    expect(progressiveTax(1200000, slabs)).toBe(80000);
  });
});

describe("daysBetween", () => {
  it("counts whole days forward", () => {
    expect(daysBetween("2026-01-01", "2026-01-31")).toBe(30);
  });
  it("is negative when reversed", () => {
    expect(daysBetween("2026-02-01", "2026-01-01")).toBe(-31);
  });
  it("returns NaN for invalid dates", () => {
    expect(Number.isNaN(daysBetween("not-a-date", "2026-01-01"))).toBe(true);
  });
});

describe("ymd", () => {
  it("splits a day count into years/months/days", () => {
    const r = ymd(400);
    expect(r.y).toBe(1);
    expect(r.m).toBe(1);
  });
  it("clamps negatives to zero", () => {
    expect(ymd(-5)).toEqual({ y: 0, m: 0, d: 0 });
  });
});

describe("n (numeric field parse)", () => {
  it("parses numbers and defaults junk to 0", () => {
    expect(n({ a: "1200.5" }, "a")).toBe(1200.5);
    expect(n({ a: "" }, "a")).toBe(0);
    expect(n({}, "missing")).toBe(0);
  });
});

import { describe, expect, it } from "vitest";
import {
  decryptString, deriveKey, encryptString, isEncryptedRecord, makeLockRecord, openLockRecord,
} from "./lock";

const salt = new Uint8Array(16).fill(7);

describe("App Lock crypto", () => {
  it("round-trips a string", async () => {
    const key = await deriveKey("correct horse battery staple", salt);
    const blob = await encryptString(key, "hello ₹18,00,000 — Priya");
    expect(await decryptString(key, blob)).toBe("hello ₹18,00,000 — Priya");
  });

  it("produces a fresh IV per encryption", async () => {
    const key = await deriveKey("pass-phrase-1", salt);
    const a = await encryptString(key, "same plaintext");
    const b = await encryptString(key, "same plaintext");
    expect(a.iv).not.toBe(b.iv);
    expect(a.data).not.toBe(b.data);
  });

  it("rejects decryption with the wrong key", async () => {
    const right = await deriveKey("right password", salt);
    const wrong = await deriveKey("wrong password", salt);
    const blob = await encryptString(right, "secret roster");
    await expect(decryptString(wrong, blob)).rejects.toThrow();
  });

  it("handles multi-megabyte payloads (chunked base64)", async () => {
    const key = await deriveKey("pass-phrase-1", salt);
    const big = "x".repeat(2_500_000); // ~ a large base64 logo
    const blob = await encryptString(key, big);
    expect(await decryptString(key, blob)).toBe(big);
  });

  it("makeLockRecord/openLockRecord verify the passphrase", async () => {
    const { record } = await makeLockRecord("my vault passphrase");
    expect(await openLockRecord("my vault passphrase", record)).not.toBeNull();
    expect(await openLockRecord("not the passphrase", record)).toBeNull();
    expect(await openLockRecord("", record)).toBeNull();
  });

  it("unlocked key from openLockRecord decrypts data encrypted at enable-time", async () => {
    const { record, key } = await makeLockRecord("season pass 9");
    const stored = await encryptString(key, JSON.stringify([{ id: "1", label: "Priya" }]));
    const reopened = await openLockRecord("season pass 9", record);
    expect(reopened).not.toBeNull();
    expect(JSON.parse(await decryptString(reopened!, stored))).toEqual([
      { id: "1", label: "Priya" },
    ]);
  });

  it("isEncryptedRecord discriminates the on-disk shapes", () => {
    expect(isEncryptedRecord({ __enc: 1, iv: "a", data: "b" })).toBe(true);
    expect(isEncryptedRecord([])).toBe(false);
    expect(isEncryptedRecord([{ id: "1" }])).toBe(false);
    expect(isEncryptedRecord(null)).toBe(false);
    expect(isEncryptedRecord("string")).toBe(false);
  });
});

import { describe, it, expect } from "vitest";
import { calculatorRegistry } from "./calculators";
import { regionById, money as fmtMoney, num as fmtNum } from "../lib/regions";
import type { CalcResult } from "../lib/calc";

/** Run a calculator's compute() the same way the UI does. */
function run(id: string, values: Record<string, string>): CalcResult {
  const spec = calculatorRegistry[id];
  if (!spec) throw new Error(`unknown calculator: ${id}`);
  const region = regionById(spec.currency ?? "IN");
  return spec.compute(values, {
    region,
    money: (v, d) => fmtMoney(v, region, { decimals: d }),
    num: (v, d) => fmtNum(v, region, d),
  });
}

const row = (r: CalcResult, label: string) => r.rows.find((x) => x.label === label)?.value ?? "";
const numOf = (s: string) => {
  const m = String(s).replace(/,/g, "").match(/-?\d+(\.\d+)?/);
  return m ? parseFloat(m[0]) : NaN;
};

describe("salary-hike-calculator", () => {
  it("computes revised salary and increment", () => {
    const r = run("salary-hike-calculator", { current: "100000", hike: "10", period: "annual" });
    expect(numOf(row(r, "Revised salary"))).toBe(110000);
    expect(numOf(row(r, "Increment amount"))).toBe(10000);
  });
});

describe("reverse-hike-calculator", () => {
  it("computes the effective hike percent", () => {
    const r = run("reverse-hike-calculator", { current: "100000", offered: "130000" });
    expect(numOf(row(r, "Effective hike"))).toBeCloseTo(30, 1);
  });
  it("is safe when current is zero (no divide-by-zero)", () => {
    const r = run("reverse-hike-calculator", { current: "0", offered: "100000" });
    expect(numOf(row(r, "Effective hike"))).toBe(0);
  });
});

describe("emi-calculator", () => {
  it("matches the standard EMI formula", () => {
    // 100000 @ 12% p.a. for 12 months → 8884.88
    const r = run("emi-calculator", { principal: "100000", rate: "12", months: "12" });
    expect(numOf(row(r, "Monthly EMI"))).toBe(8885);
  });
});

describe("india-hra-exemption", () => {
  it("takes the least of the three statutory values (Section 10(13A))", () => {
    // a=20000, b=18000-4000=14000, 50% basic=20000 → exempt 14000
    const r = run("india-hra-exemption", { basic: "40000", hra: "20000", rent: "18000", metro: "yes" });
    expect(numOf(row(r, "Exempt HRA (monthly)"))).toBe(14000);
  });
});

describe("india-take-home (new regime, FY2024-25)", () => {
  it("applies the ₹75,000 standard deduction and §87A marginal relief", () => {
    // Pinned regression: with the correct ₹75k standard deduction the annual
    // take-home is ₹10,66,783 (a ₹50k deduction would give a different number).
    const r = run("india-take-home", { ctc: "1200000", basicPct: "40", regime: "new" });
    expect(numOf(row(r, "Annual take-home"))).toBe(1066783);
    expect(numOf(row(r, "Income tax / TDS (−)"))).toBe(64529);
  });

  it("charges no income tax when the regime is ignored", () => {
    const r = run("india-take-home", { ctc: "1200000", basicPct: "40", regime: "none" });
    expect(numOf(row(r, "Income tax / TDS (−)"))).toBe(0);
  });
});

describe("ksa-gratuity", () => {
  it("formats amounts in Saudi Riyal (currency fix)", () => {
    const r = run("ksa-gratuity", { wage: "12000", years: "7", reason: "termination" });
    const emphasized = r.rows.find((x) => x.emphasize)?.value ?? "";
    expect(emphasized).toMatch(/SAR|﷼/);
  });
});

